  const [model, setModel] = useState(appsmith.model || {});
  const [sortKey, setSortKey] = useState(ID_KEY);
  const [sortDir, setSortDir] = useState("desc");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [gotoVal, setGotoVal] = useState("");
  const [q, setQ] = useState("");

  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];

  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    if (!term) return data;
    return data.filter((r) => COLS.some((c) => {
      const v = r[c.key];
      return v != null && String(v).toLowerCase().indexOf(term) !== -1;
    }));
  }, [data, q]);

  const rows = useMemo(() => {
    const list = filtered.slice();
    list.sort(function (a, b) {
      if (NUM_KEYS.indexOf(sortKey) !== -1) {
        const av = Number(a[sortKey]) || 0, bv = Number(b[sortKey]) || 0;
        return sortDir === "asc" ? av - bv : bv - av;
      }
      if (DATE_KEYS.indexOf(sortKey) !== -1) {
        const av = a[sortKey] ? new Date(a[sortKey]).getTime() : 0, bv = b[sortKey] ? new Date(b[sortKey]).getTime() : 0;
        return sortDir === "asc" ? av - bv : bv - av;
