    React.createElement("span", { className: (sortKey === k && sortDir === "asc") ? "active" : "" }, "\u25B2"),
    React.createElement("span", { className: (sortKey === k && sortDir === "desc") ? "active" : "" }, "\u25BC"));

  const cell = (r, key) => {
    const v = r[key];
    return v == null ? "" : String(v);
  };

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "search" },
      React.createElement("input", { type: "text", placeholder: "Search", value: q, onChange: (e) => setQ(e.target.value) })),
    React.createElement("div", { className: "meta", style: { textAlign: META.align } }, META.prefix, React.createElement("b", null, rows.length), META.suffix),
    React.createElement("div", { className: "scroll" },
      React.createElement("table", { className: "tbl" },
        React.createElement("thead", null,
          React.createElement("tr", null,
            COLS.map((c) => React.createElement("th", { key: c.key, onClick: () => onSort(c.key) }, c.label, arrows(c.key))),
            HAS_ACTION ? React.createElement("th", { className: "noSort", key: "__action" }, "") : null)),
        React.createElement("tbody", null,
